<?php require __DIR__.'/_start.php'; ?>
<section class="customer-card"><h2>Tamamlanan bakımınızı değerlendirin</h2><p>Değerlendirmeler yönetici incelemesi sonrasında adınızın yalnızca başharfiyle sitede yayınlanabilir. Düzenlediğiniz yorum yeniden incelemeye alınır.</p><?php if(!$completed): ?><p class="muted">Henüz tamamlanan bir randevunuz yok. Tamamlanan bakımlarınız burada listelenir.</p><?php else: ?><form method="post" action="<?= e(url('customer/reviews/save')) ?>"><?= App\Core\Csrf::field() ?><label class="form-label" for="review-appointment">Tamamlanan randevu</label><select class="form-select mb-3" id="review-appointment" name="appointment_id" required><?php foreach($completed as$a): ?><option value="<?= (int)$a['id'] ?>">#<?= (int)$a['id'] ?> · <?= e($a['service_name']) ?> · <?= e(date('d.m.Y',strtotime($a['start_at']))) ?></option><?php endforeach ?></select><label class="form-label" for="review-rating">Puan</label><select class="form-select mb-3" id="review-rating" name="rating" required><?php foreach(range(5,1)as$n): ?><option value="<?= $n ?>"><?= $n ?> / 5</option><?php endforeach ?></select><label class="form-label" for="review-comment">Değerlendirmeniz</label><textarea class="form-control mb-3" id="review-comment" name="comment" minlength="3" maxlength="2000" rows="4" required></textarea><button type="submit" class="btn btn-lumera">Değerlendirmeyi kaydet</button></form><?php endif ?></section>
<section class="customer-card mt-4"><h2>Değerlendirmelerim</h2><?php if(!$reviews): ?><p class="muted">Henüz değerlendirme göndermediniz.</p><?php else: ?><?php foreach($reviews as$r): ?><article class="border-bottom py-3"><h3 class="h5"><?= e($r['service_name']) ?> · <?= (int)$r['rating'] ?> / 5</h3><p><?= e($r['comment']) ?></p><small>#<?= (int)$r['appointment_id'] ?> · <?= $r['is_visible']?'Yayında':'İncelemede / gizli' ?></small></article><?php endforeach ?><?php endif ?></section>
<?php require __DIR__.'/_end.php'; ?>
